(function(T){
  'use strict';
  if(!T) return;

  var taskStatuses={todo:'Запланировано',doing:'В работе',done:'Выполнено',skipped:'Не требуется'};
  var approvalStates={draft:'Черновик',review:'На согласовании',approved:'Принято',changes:'Нужны изменения'};
  var selectedTask=null, selectedApproval=null, taskView='list', taskQuery='', taskScope='all', approvalFilter='all';
  function esc(v){return T.escape(String(v==null?'':v));}
  function id(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);}
  function project(){return T.project()||{id:'p1',name:'Алина и Даниил'};}
  function tone(status){return status==='done'?'green':status==='doing'?'rose':status==='skipped'?'gray':'amber';}
  function dateLabel(v){var d=new Date(v+'T12:00:00');return isNaN(d)?v:d.toLocaleDateString('ru-RU',{day:'numeric',month:'short'});}
  function ensureData(){
    if(!Array.isArray(T.data.tasks)||!T.data.tasks.length) T.data.tasks=[
      {id:'t1',projectId:'p1',title:'Утвердить меню банкета',phase:'Последние детали',due:'2026-09-06',relative:'−13 дней',assignee:'Алина',status:'doing',priority:'high',note:'Нужно выбрать один из двух вариантов ресторана.',links:['a1'],comments:[['Мария','Ждём финальный список аллергий.','8 сентября']]},
      {id:'t2',projectId:'p1',title:'Выбрать оформление церемонии',phase:'Концепция',due:'2026-09-10',relative:'−9 дней',assignee:'Пара',status:'doing',priority:'high',note:'Связано с тремя вариантами оформления.',links:['a1'],comments:[['Даниил','Нравится вариант с тёплым текстилем.','8 сентября']]},
      {id:'t3',projectId:'p1',title:'Собрать ответы гостей',phase:'Гости',due:'2026-09-12',relative:'−7 дней',assignee:'Даниил',status:'todo',priority:'medium',note:'4 приглашения ещё без ответа.',links:[],comments:[]},
      {id:'t4',projectId:'p1',title:'Проверить рассадку',phase:'Гости',due:'2026-09-14',relative:'−5 дней',assignee:'Мария',status:'todo',priority:'medium',note:'Откроется после финальных RSVP.',blockedBy:'t3',links:[],comments:[]},
      {id:'t5',projectId:'p1',title:'Подтвердить время приезда декоратора',phase:'Подрядчики',due:'2026-09-11',relative:'−8 дней',assignee:'Мария',status:'todo',priority:'high',note:'Связано с окном монтажа на площадке.',links:[],comments:[]},
      {id:'t6',projectId:'p1',title:'Утвердить тайминг пары',phase:'День свадьбы',due:'2026-09-16',relative:'−3 дня',assignee:'Алина',status:'todo',priority:'medium',note:'Проверьте сборы, церемонию и первый танец.',links:[],comments:[]},
      {id:'t7',projectId:'p1',title:'Оплатить остаток за декор',phase:'Финансы',due:'2026-09-14',relative:'−5 дней',assignee:'Мария',status:'todo',priority:'high',note:'180 000 ₽ после утверждения варианта.',links:['a1'],comments:[]},
      {id:'t8',projectId:'p1',title:'Передать план рассадки ресторану',phase:'Гости',due:'2026-09-17',relative:'−2 дня',assignee:'Мария',status:'todo',priority:'medium',note:'Версия для печати и таблица гостевых ограничений.',blockedBy:'t4',links:[],comments:[]},
      {id:'t9',projectId:'p1',title:'Проверить трансфер гостей',phase:'Логистика',due:'2026-09-15',relative:'−4 дня',assignee:'Даниил',status:'todo',priority:'low',note:'Сверить адреса и время отправления.',links:[],comments:[]},
      {id:'t10',projectId:'p1',title:'Собрать контакты подрядчиков на день',phase:'День свадьбы',due:'2026-09-13',relative:'−6 дней',assignee:'Мария',status:'doing',priority:'medium',note:'Один лист для команды и пары.',links:[],comments:[]},
      {id:'t11',projectId:'p1',title:'Выбрать площадку',phase:'Подготовка',due:'2026-03-12',relative:'завершено',assignee:'Пара',status:'done',priority:'low',note:'Усадьба «Липы» подтверждена.',links:[],comments:[['Алина','Площадка очень подходит по свету и саду.','12 марта']]},
      {id:'t12',projectId:'p1',title:'Заказать welcome-зону',phase:'Концепция',due:'2026-09-05',relative:'не требуется',assignee:'Мария',status:'skipped',priority:'low',note:'Решили использовать декор входной группы.',links:[],comments:[]}
    ];
    if(!Array.isArray(T.data.approvals)||!T.data.approvals.length) T.data.approvals=[
      {id:'a1',projectId:'p1',title:'Оформление церемонии',category:'Декор',due:'2026-09-10',state:'review',version:2,rule:'any',approvers:['Алина','Даниил'],selected:'o2',options:[
        {id:'o1',name:'Садовая история',price:85000,style:'garden',description:'Живые цветы, текстиль и монтаж. Спокойная палитра с зеленью.',pros:'Много живой фактуры, мягкий фон для церемонии.'},
        {id:'o2',name:'Тёплый вечер',price:72000,style:'warm',description:'Тканевая композиция, сезонные цветы, доставка и демонтаж.',pros:'Поддерживает свет усадьбы и укладывается в бюджет.'},
        {id:'o3',name:'Белая церемония',price:96000,style:'light',description:'Светлая флористика и арка. Все элементы перечислены в смете.',pros:'Более формальный образ и заметный акцент в кадре.'}
      ],versions:[['v2','8 сентября','Мария','Добавлены состав и стоимость вариантов.'],['v1','5 сентября','Мария','Первый подбор декора.']],comments:[['Мария','Добавила состав каждого варианта. После выбора отдельно применим сумму к смете.','8 сентября'],['Даниил','Нравится тёплый текстиль и невысокая арка.','8 сентября']]},
      {id:'a2',projectId:'p1',title:'Музыка церемонии',category:'Сценарий',due:'2026-09-12',state:'review',version:1,rule:'all',approvers:['Алина','Даниил'],selected:null,options:[
        {id:'o1',name:'Струнный дуэт',price:32000,style:'string',description:'Две скрипки, выход пары и фоновая музыка во время сбора.',pros:'Живой звук и камерное звучание.'},
        {id:'o2',name:'Пиано и вокал',price:28000,style:'piano',description:'Пианист и вокалистка, две выбранные композиции.',pros:'Более личная подача любимых песен.'},
        {id:'o3',name:'Плейлист без артистов',price:0,style:'playlist',description:'Заранее собранный плейлист и звук площадки.',pros:'Минимальный бюджет и полный контроль треков.'}
      ],versions:[['v1','7 сентября','Мария','Собраны три формата музыки.']],comments:[]},
      {id:'a3',projectId:'p1',title:'Маршрут трансфера',category:'Логистика',due:'2026-09-14',state:'draft',version:1,rule:'any',approvers:['Алина'],selected:null,options:[
        {id:'o1',name:'Один общий рейс',price:18000,style:'route',description:'Автобус от центра города до усадьбы и обратно после ужина.',pros:'Простой маршрут для большинства гостей.'},
        {id:'o2',name:'Два рейса',price:26000,style:'route2',description:'Дневной и вечерний выезды с разным временем возврата.',pros:'Больше гибкости для гостей с детьми.'},
        {id:'o3',name:'Только обратный трансфер',price:12000,style:'night',description:'Гости приезжают самостоятельно, автобус работает после праздника.',pros:'Подходит для гостей на личных машинах.'}
      ],versions:[['v1','8 сентября','Мария','Черновик для первичной оценки.']],comments:[]}
    ];
  }
  function tasks(){ensureData();return T.state.mode==='empty'?[]:T.data.tasks.filter(function(x){return x.projectId===project().id;});}
  function approvals(){ensureData();return T.state.mode==='empty'?[]:T.data.approvals.filter(function(x){return x.projectId===project().id;});}
  function taskById(v){return tasks().find(function(x){return x.id===v;})||tasks()[0];}
  function approvalById(v){return approvals().find(function(x){return x.id===v;})||approvals()[0];}
  function goTask(v){selectedTask=v;T.state.detailId=v;T.go('task-detail');}
  function goApproval(v){selectedApproval=v;T.state.detailId=v;T.go('approval-detail');}
  function taskRow(t){return '<tr><td><button class="wf-check '+(t.status==='done'?'is-done':'')+'" data-action="wf-task-cycle" data-id="'+t.id+'" aria-label="Изменить статус '+esc(t.title)+'">'+(t.status==='done'?'✓':'')+'</button></td><td><button class="wf-row-title" data-action="wf-task-open" data-id="'+t.id+'">'+esc(t.title)+'<small>'+esc(t.note)+'</small></button></td><td><span class="wf-relative">'+esc(t.relative)+'</span><small>'+dateLabel(t.due)+'</small></td><td>'+T.avatar(t.assignee)+'<span class="wf-person">'+esc(t.assignee)+'</span></td><td>'+T.badge(taskStatuses[t.status],tone(t.status))+'</td></tr>';}
  function filteredTasks(){return tasks().filter(function(t){var match=!taskQuery||(t.title+' '+t.note+' '+t.assignee).toLowerCase().indexOf(taskQuery.toLowerCase())>=0;return match&&(taskScope==='all'||t.assignee==='Мария');});}
  function taskList(){var rows=filteredTasks();return '<section class="panel wf-table-panel"><div class="table-wrap"><table class="data-table wf-task-table"><thead><tr><th></th><th>Задача</th><th>Срок</th><th>Ответственный</th><th>Статус</th></tr></thead><tbody>'+rows.map(taskRow).join('')+'</tbody></table></div></section>'+(rows.length?'':T.empty('Задачи не найдены','Смените фильтр или добавьте первое дело.',T.button('+ Задача','wf-task-create')));}
  function taskBoard(){var cols=['todo','doing','done','skipped'];return '<div class="wf-board">'+cols.map(function(s){var list=filteredTasks().filter(function(t){return t.status===s;});return '<section><header><h3>'+taskStatuses[s]+'</h3><span>'+list.length+'</span></header>'+list.map(function(t){return '<button class="wf-board-card" data-action="wf-task-open" data-id="'+t.id+'"><small>'+esc(t.relative)+'</small><strong>'+esc(t.title)+'</strong><span>'+esc(t.assignee)+'</span></button>';}).join('')+(list.length?'':'<p class="subtle">Нет задач</p>')+'</section>';}).join('')+'</div>';}
  function taskCalendar(){var list=filteredTasks().slice().sort(function(a,b){return a.due.localeCompare(b.due);});return '<section class="panel panel-pad wf-task-calendar"><div class="wf-calendar-line"><span>Сентябрь 2026</span><small>сроки до свадьбы</small></div>'+list.map(function(t){return '<button data-action="wf-task-open" data-id="'+t.id+'"><time>'+dateLabel(t.due)+'</time><i class="'+t.status+'"></i><span><strong>'+esc(t.title)+'</strong><small>'+esc(t.assignee)+' · '+taskStatuses[t.status]+'</small></span></button>';}).join('')+'</section>';}
  function renderTasks(){var done=tasks().filter(function(t){return t.status==='done';}).length;return T.heading('План подготовки',tasks().length?done+' из '+tasks().length+' задач выполнено · сроки видны относительно даты свадьбы':'Здесь появятся задачи подготовки и ближайшие сроки.',T.button(T.icon('plus')+' Задача','wf-task-create'))+'<div class="toolbar wf-toolbar"><label class="search-input">'+T.icon('search',16)+'<input data-action="wf-task-search" value="'+esc(taskQuery)+'" placeholder="Найти задачу" aria-label="Найти задачу"></label><div class="segmented"><button data-action="wf-task-view" data-view="list" class="'+(taskView==='list'?'active':'')+'">Список</button><button data-action="wf-task-view" data-view="board" class="'+(taskView==='board'?'active':'')+'">Доска</button><button data-action="wf-task-view" data-view="calendar" class="'+(taskView==='calendar'?'active':'')+'">Календарь</button></div><span class="spacer"></span><select data-action="wf-task-scope" aria-label="Показать задачи"><option value="all" '+(taskScope==='all'?'selected':'')+'>Все участники</option><option value="mine" '+(taskScope==='mine'?'selected':'')+'>Мои задачи</option></select></div>'+(taskView==='board'?taskBoard():taskView==='calendar'?taskCalendar():taskList());}
  function taskDetail(){var t=taskById(T.state.detailId||selectedTask);if(!t)return T.heading('Задача','')+T.empty('Задача пока не выбрана','Вернитесь к плану или создайте первую задачу.',T.button('+ Задача','wf-task-create'))+'<button class="link-button wf-back" data-go="tasks">← Вернуться к плану</button>';var link=t.links&&t.links[0]?approvalById(t.links[0]):null;return T.heading(t.title,t.phase+' · '+t.relative+' · '+dateLabel(t.due),'<button class="btn secondary" data-action="wf-task-edit" data-id="'+t.id+'">'+T.icon('edit',15)+' Изменить</button>')+'<div class="wf-detail-layout"><section class="panel panel-pad"><div class="wf-status-line">'+T.badge(taskStatuses[t.status],tone(t.status))+'<button class="link-button" data-action="wf-task-cycle" data-id="'+t.id+'">Отметить '+(t.status==='done'?'незавершённой':'выполненной')+'</button></div><p class="wf-detail-copy">'+esc(t.note)+'</p><dl class="wf-detail-meta"><div><dt>Срок</dt><dd>'+esc(t.relative)+' · '+dateLabel(t.due)+'</dd></div><div><dt>Ответственный</dt><dd>'+T.avatar(t.assignee)+esc(t.assignee)+'</dd></div><div><dt>Приоритет</dt><dd>'+T.badge(t.priority==='high'?'Высокий':t.priority==='medium'?'Обычный':'Низкий',t.priority==='high'?'amber':'gray')+'</dd></div><div><dt>Зависимости</dt><dd>'+(t.blockedBy?'Сначала завершить «'+esc(taskById(t.blockedBy).title)+'»':'Нет')+'</dd></div></dl>'+(link?'<button class="wf-linked-card" data-action="wf-approval-open" data-id="'+link.id+'"><span>Связанное согласование</span><strong>'+esc(link.title)+'</strong><small>Открыть варианты →</small></button>':'')+'</section><aside class="panel panel-pad wf-comments"><h3>Обсуждение</h3>'+(t.comments||[]).map(function(c){return '<article><span>'+T.avatar(c[0])+'</span><p><strong>'+esc(c[0])+'</strong><small>'+esc(c[2])+'</small>'+esc(c[1])+'</p></article>';}).join('')+'<form data-action="wf-task-comment"><textarea name="comment" placeholder="Добавить комментарий"></textarea><button class="btn secondary small">Отправить</button></form></aside></div>'+'<button class="link-button wf-back" data-go="tasks">← Вернуться к плану</button>';}
  function taskModal(item){var t=item||{title:'',phase:'Подготовка',due:'2026-09-15',relative:'−4 дня',assignee:'Мария',status:'todo',priority:'medium',note:''};var isEdit=!!item;T.modal({title:isEdit?'Изменить задачу':'Новая задача',wide:true,body:'<form class="wf-form" data-action="wf-task-save" data-id="'+(t.id||'')+'">'+T.field('Название',T.input('title',t.title,'Например, утвердить меню'))+T.field('Этап',T.select('phase',['Подготовка','Концепция','Подрядчики','Гости','Финансы','День свадьбы'],t.phase))+T.field('Срок',T.input('due',t.due,'','date'))+T.field('Срок относительно свадьбы',T.input('relative',t.relative,'−7 дней'))+T.field('Ответственный',T.select('assignee',['Мария','Алина','Даниил','Пара'],t.assignee))+T.field('Статус',T.select('status',[['todo','Запланировано'],['doing','В работе'],['done','Выполнено'],['skipped','Не требуется']],t.status))+T.field('Приоритет',T.select('priority',[['low','Низкий'],['medium','Обычный'],['high','Высокий']],t.priority))+T.field('Описание','<textarea name="note" rows="4">'+esc(t.note)+'</textarea>',true)+'<div class="wf-modal-actions"><button type="button" class="btn secondary" data-action="wf-modal-close">Отмена</button><button class="btn">'+(isEdit?'Сохранить изменения':'Создать задачу')+'</button></div></form>'});}
  function approvalCard(a){var selected=a.options.find(function(o){return o.id===a.selected;});return '<button class="wf-approval-card" data-action="wf-approval-open" data-id="'+a.id+'"><span class="wf-approval-top">'+T.badge(approvalStates[a.state],a.state==='approved'?'green':a.state==='changes'?'amber':'rose')+'<time>до '+dateLabel(a.due)+'</time></span><h3>'+esc(a.title)+'</h3><p>'+esc(a.category)+' · версия '+a.version+'</p><footer><span>'+a.options.length+' варианта</span><strong>'+(selected?esc(selected.name):'Открыть →')+'</strong></footer></button>';}
  function renderApprovals(){var list=approvals().filter(function(a){return approvalFilter==='all'||a.state===approvalFilter;});return T.heading('Согласования','Варианты, решения и комментарии остаются в истории подготовки.',T.button(T.icon('plus')+' Согласование','wf-approval-create'))+'<div class="toolbar wf-toolbar"><div class="segmented"><button class="'+(approvalFilter==='all'?'active':'')+'" data-action="wf-approval-filter" data-filter="all">Все</button><button class="'+(approvalFilter==='review'?'active':'')+'" data-action="wf-approval-filter" data-filter="review">На согласовании</button><button class="'+(approvalFilter==='approved'?'active':'')+'" data-action="wf-approval-filter" data-filter="approved">Принятые</button></div><span class="spacer"></span><span class="subtle">'+list.length+' тем</span></div><div class="cards-grid wf-approvals-grid">'+list.map(approvalCard).join('')+'</div>'+(list.length?'':T.empty('Здесь пока нет согласований','Создайте тему и добавьте варианты.',T.button('+ Согласование','wf-approval-create')));}
  function optionSwatch(o){return '<div class="wf-option-art '+esc(o.style)+'"><i></i><i></i><i></i></div>';}
  function approvalDetail(){var a=approvalById(T.state.detailId||selectedApproval);if(!a)return T.heading('Согласование','')+T.empty('Тема пока не выбрана','Создайте первую тему, чтобы сравнить варианты.',T.button('+ Согласование','wf-approval-create'))+'<button class="link-button wf-back" data-go="approvals">← Все согласования</button>';var selected=a.options.find(function(o){return o.id===a.selected;});return T.heading(a.title,'Версия '+a.version+' · отправлено 8 сентября · решение до '+dateLabel(a.due),'<button class="btn secondary" data-action="wf-approval-edit" data-id="'+a.id+'">'+T.icon('edit',15)+' Изменить</button>')+'<section class="wf-approval-banner">'+T.badge(approvalStates[a.state],a.state==='approved'?'green':a.state==='changes'?'amber':'rose')+'<span>Согласующие: '+esc(a.approvers.join(' и '))+' · '+(a.rule==='all'?'нужны решения всех':'достаточно одного решения')+'</span><button class="link-button" data-action="wf-approval-history" data-id="'+a.id+'">История версий</button></section><div class="wf-options">'+a.options.map(function(o){var is=o.id===a.selected;return '<button class="wf-option '+(is?'selected':'')+'" data-action="wf-option-select" data-id="'+a.id+'" data-option="'+o.id+'" aria-pressed="'+is+'">'+optionSwatch(o)+'<h3>'+esc(o.name)+'</h3><strong>'+T.money(o.price)+'</strong><p>'+esc(o.description)+'</p><small>'+esc(o.pros)+'</small><em>'+(is?'✓ Выбран для решения':'Выбрать вариант')+'</em></button>';}).join('')+'</div><section class="panel wf-approval-footer"><div><h3>'+ (selected?'Выбран вариант «'+esc(selected.name)+'»':'Выберите вариант для решения') +'</h3><p class="subtle">Утверждение фиксирует версию. Выплата этим действием не создаётся.</p></div><div class="inline"><button class="btn secondary" data-action="wf-approval-changes" data-id="'+a.id+'">Нужны изменения</button><button class="btn primary" data-action="wf-approval-approve" data-id="'+a.id+'" '+(a.selected&&a.state!=='approved'?'':'disabled')+'>'+(a.state==='approved'?'Вариант утверждён':'Утвердить вариант')+'</button></div></section><section class="panel panel-pad wf-comments"><h3>Обсуждение</h3>'+(a.comments||[]).map(function(c){return '<article><span>'+T.avatar(c[0])+'</span><p><strong>'+esc(c[0])+'</strong><small>'+esc(c[2])+'</small>'+esc(c[1])+'</p></article>';}).join('')+'<form data-action="wf-approval-comment" data-id="'+a.id+'"><textarea name="comment" placeholder="Добавить комментарий"></textarea><button class="btn secondary small">Отправить</button></form></section><button class="link-button wf-back" data-go="approvals">← Все согласования</button>';}
  function approvalModal(item){var a=item||{title:'',category:'Декор',due:'2026-09-14',rule:'any'};T.modal({title:item?'Изменить согласование':'Новое согласование',wide:true,body:'<form class="wf-form" data-action="wf-approval-save" data-id="'+(a.id||'')+'">'+T.field('Тема',T.input('title',a.title,'Например, музыка церемонии'))+T.field('Категория',T.select('category',['Декор','Сценарий','Логистика','Подрядчики'],a.category))+T.field('Дедлайн',T.input('due',a.due,'','date'))+T.field('Правило решения',T.select('rule',[['any','Достаточно одного решения'],['all','Нужны решения всех']],a.rule))+T.field('Согласующие',T.input('approvers',(a.approvers||['Алина','Даниил']).join(', '),'Алина, Даниил'),true)+'<p class="wf-form-note">Варианты добавляются после сохранения темы. В макете появятся три оформленных варианта.</p><div class="wf-modal-actions"><button type="button" class="btn secondary" data-action="wf-modal-close">Отмена</button><button class="btn">'+(item?'Сохранить изменения':'Создать согласование')+'</button></div></form>'});}
  T.registerActions({
    'wf-task-open':function(el){goTask(el.dataset.id);},
    'wf-task-create':function(){taskModal(null);},
    'wf-task-edit':function(el){taskModal(taskById(el.dataset.id));},
    'wf-task-view':function(el){taskView=el.dataset.view;T.render();},
    'wf-task-scope':function(el){taskScope=el.value;T.render();},
    'wf-task-search':function(el){taskQuery=el.value;T.render();},
    'wf-task-cycle':function(el){var t=taskById(el.dataset.id);t.status=t.status==='done'?'todo':'done';T.toast(t.status==='done'?'Задача отмечена выполненной':'Задача возвращена в план');T.render();},
    'wf-task-save':function(el,event){event.preventDefault();var f=T.formValues(el),t=el.dataset.id?taskById(el.dataset.id):null;if(t)Object.assign(t,f);else{t=Object.assign({id:id('task'),projectId:project().id,comments:[],links:[]},f);T.data.tasks.unshift(t);}T.closeModal();goTask(t.id);T.toast('Задача сохранена');},
    'wf-task-comment':function(el,event){event.preventDefault();var text=T.formValues(el).comment;if(!text)return;var t=taskById(T.state.detailId||selectedTask);t.comments.push(['Мария',text,'сейчас']);T.render();},
    'wf-approval-open':function(el){goApproval(el.dataset.id);},
    'wf-approval-create':function(){approvalModal(null);},
    'wf-approval-edit':function(el){approvalModal(approvalById(el.dataset.id));},
    'wf-approval-filter':function(el){approvalFilter=el.dataset.filter;T.render();},
    'wf-option-select':function(el){var a=approvalById(el.dataset.id);if(a.selected!==el.dataset.option)a.state='review';a.selected=el.dataset.option;T.render();},
    'wf-approval-approve':function(el){var a=approvalById(el.dataset.id);a.state='approved';a.comments.push(['Алина','Вариант принят.','сейчас']);T.toast('Решение сохранено в истории');T.render();},
    'wf-approval-changes':function(el){var a=approvalById(el.dataset.id);T.modal({title:'Запросить изменения',body:'<form class="wf-form" data-action="wf-approval-request" data-id="'+a.id+'">'+T.field('Что изменить','<textarea required name="comment" rows="4" placeholder="Например, убрать высокий цветочный акцент"></textarea>',true)+'<div class="wf-modal-actions"><button type="button" class="btn secondary" data-action="wf-modal-close">Отмена</button><button class="btn primary">Отправить запрос</button></div></form>'});},
    'wf-approval-request':function(el,event){event.preventDefault();var a=approvalById(el.dataset.id),text=T.formValues(el).comment;a.state='changes';a.comments.push(['Алина',text,'сейчас']);T.closeModal();T.render();T.toast('Запрос изменений добавлен');},
    'wf-approval-save':function(el,event){event.preventDefault();var f=T.formValues(el),a=el.dataset.id?approvalById(el.dataset.id):null;if(a){a.title=f.title;a.category=f.category;a.due=f.due;a.rule=f.rule;a.approvers=f.approvers.split(',').map(function(x){return x.trim();}).filter(Boolean);}else{a={id:id('approval'),projectId:project().id,title:f.title,category:f.category,due:f.due,rule:f.rule,approvers:f.approvers.split(',').map(function(x){return x.trim();}).filter(Boolean),state:'draft',version:1,selected:null,options:[{id:'o1',name:'Первый вариант',price:0,style:'garden',description:'Добавьте состав решения и стоимость.',pros:'Черновой вариант.'},{id:'o2',name:'Второй вариант',price:0,style:'warm',description:'Добавьте состав решения и стоимость.',pros:'Черновой вариант.'},{id:'o3',name:'Третий вариант',price:0,style:'light',description:'Добавьте состав решения и стоимость.',pros:'Черновой вариант.'}],versions:[['v1','сейчас','Мария','Создано в макете.']],comments:[]};T.data.approvals.unshift(a);}T.closeModal();goApproval(a.id);T.toast('Согласование сохранено');},
    'wf-approval-comment':function(el,event){event.preventDefault();var text=T.formValues(el).comment;if(!text)return;var a=approvalById(el.dataset.id);a.comments.push(['Мария',text,'сейчас']);T.render();},
    'wf-approval-history':function(el){var a=approvalById(el.dataset.id);T.modal({title:'История версий',body:'<div class="wf-history">'+a.versions.map(function(v){return '<article><span>'+esc(v[0])+'</span><p><strong>'+esc(v[2])+' · '+esc(v[1])+'</strong>'+esc(v[3])+'</p></article>';}).join('')+'</div>'});},
    'wf-modal-close':function(){T.closeModal();}
  });
  T.register({
    tasks:{title:'План подготовки',scope:'project',tab:'tasks',render:renderTasks},
    'task-detail':{title:'Задача',scope:'project',tab:'tasks',render:taskDetail},
    approvals:{title:'Согласования',scope:'project',tab:'approvals',render:renderApprovals},
    'approval-detail':{title:'Согласование',scope:'project',tab:'approvals',render:approvalDetail}
  });
})(window.Tie);
